toolScript:
// Web Audio Context
        const AudioContext = window.AudioContext || window.webkitAudioContext;
        let audioCtx;
        let oscillator;
        let gainNode;
        const frequencies = [250, 500, 1000, 2000, 4000, 8000, 12000, 16000];
        let currentFreqIndex = 2;
        let currentEar = 'left';
        const resultsLeft = {};
        const resultsRight = {};
        let chart;
        function initAudio() {
            if (!audioCtx) {
                audioCtx = new AudioContext();
                gainNode = audioCtx.createGain();
            }
            if (audioCtx.state === 'suspended') {
                audioCtx.resume();
            }
        }
        function playReference() {
            initAudio();
            const osc = audioCtx.createOscillator();
            const gn = audioCtx.createGain();
            osc.connect(gn);
            gn.connect(audioCtx.destination);
            osc.type = 'sine';
            osc.frequency.value = 400;
            gn.gain.value = 0.05;
            osc.start();
            setTimeout(() => {
                osc.stop();
                osc.disconnect();
            }, 1500);
        }
        function startTest() {
            document.getElementById('calibration-step').classList.add('hidden');
            document.getElementById('test-interface').classList.remove('hidden');
            initChart();
            window.scrollTo({ top: document.querySelector('.tool-card').offsetTop - 20, behavior: 'smooth' });
        }
        function setEar(ear) {
            currentEar = ear;
            const btnLeft = document.getElementById('btn-left');
            const btnRight = document.getElementById('btn-right');
            if (ear === 'left') {
                btnLeft.className = "flex-1 py-3.5 rounded-xl font-black text-xs bg-blue-600 text-white shadow-lg transition-all uppercase tracking-widest";
                btnRight.className = "flex-1 py-3.5 rounded-xl font-black text-xs bg-white text-slate-500 border-2 border-slate-100 hover:border-red-400 transition-all uppercase tracking-widest";
            } else {
                btnRight.className = "flex-1 py-3.5 rounded-xl font-black text-xs bg-red-600 text-white shadow-lg transition-all uppercase tracking-widest";
                btnLeft.className = "flex-1 py-3.5 rounded-xl font-black text-xs bg-white text-slate-500 border-2 border-slate-100 hover:border-blue-400 transition-all uppercase tracking-widest";
            }
        }
        function changeFreq(dir) {
            currentFreqIndex += dir;
            if (currentFreqIndex < 0) currentFreqIndex = 0;
            if (currentFreqIndex >= frequencies.length) currentFreqIndex = frequencies.length - 1;
            document.getElementById('freq-display').innerText = frequencies[currentFreqIndex];
            document.getElementById('vol-slider').value = 0;
            updateVolDisplay();
        }
        function updateVolDisplay() {
            const val = document.getElementById('vol-slider').value;
            document.getElementById('vol-display').innerText = `${val} dBHL`;
        }
        function playTone() {
            initAudio();
            const freq = frequencies[currentFreqIndex];
            const db = parseInt(document.getElementById('vol-slider').value);
            // Equation logic: Human-understandable variable mapping
            // Maximum clinical output assumed at 80dB (Digital Limit)
            const gainVal = Math.pow(10, (db - 80) / 20) * 0.5;
            oscillator = audioCtx.createOscillator();
            const panner = audioCtx.createStereoPanner();
            oscillator.type = 'sine';
            oscillator.frequency.value = freq;
            panner.pan.value = currentEar === 'left' ? -1 : 1;
            oscillator.connect(gainNode);
            gainNode.connect(panner);
            panner.connect(audioCtx.destination);
            gainNode.gain.setValueAtTime(gainVal, audioCtx.currentTime);
            oscillator.start();
            document.getElementById('play-tone-btn').classList.add('playing-btn');
        }
        function stopTone() {
            if (oscillator) {
                oscillator.stop();
                oscillator.disconnect();
                oscillator = null;
            }
            document.getElementById('play-tone-btn').classList.remove('playing-btn');
        }
        function markPoint() {
            const freq = frequencies[currentFreqIndex];
            const db = parseInt(document.getElementById('vol-slider').value);
            if (currentEar === 'left') resultsLeft[freq] = db;
            else resultsRight[freq] = db;
            updateChart();
            if (currentFreqIndex < frequencies.length - 1) {
                setTimeout(() => changeFreq(1), 200);
            }
        }
        function initChart() {
            const ctx = document.getElementById('audiogramChart').getContext('2d');
            chart = new Chart(ctx, {
                type: 'line',
                data: {
                    labels: frequencies,
                    datasets: [
                        {
                            label: 'Left Ear (X)',
                            data: [],
                            borderColor: '#3b82f6',
                            pointStyle: 'crossRot',
                            pointRadius: 8,
                            borderWidth: 3,
                            showLine: true,
                            tension: 0.2
                        },
                        {
                            label: 'Right Ear (O)',
                            data: [],
                            borderColor: '#ef4444',
                            pointStyle: 'circle',
                            pointRadius: 8,
                            borderWidth: 3,
                            showLine: true,
                            tension: 0.2
                        }
                    ]
                },
                options: {
                    responsive: true,
                    maintainAspectRatio: false,
                    scales: {
                        y: {
                            reverse: true,
                            min: -10,
                            max: 90,
                            title: { display: true, text: 'Threshold (dB HL)', font: { weight: 'bold' } },
                            grid: { color: '#f1f5f9' }
                        },
                        x: {
                            title: { display: true, text: 'Pitch (Hz)', font: { weight: 'bold' } },
                            type: 'logarithmic',
                            grid: { color: '#f1f5f9' }
                        }
                    },
                    plugins: {
                        legend: { position: 'bottom', labels: { font: { weight: 'bold' }, padding: 20 } }
                    }
                }
            });
        }
        function updateChart() {
            const lData = frequencies.map(f => resultsLeft[f] !== undefined ? resultsLeft[f] : null);
            const rData = frequencies.map(f => resultsRight[f] !== undefined ? resultsRight[f] : null);
            chart.data.datasets[0].data = lData;
            chart.data.datasets[1].data = rData;
            chart.update();
        }
        document.addEventListener('DOMContentLoaded', updateVolDisplay);
